-- Seed: Minna no Nihongo — Bài 7-12 (từ vựng)
-- Nguồn: PDF Minato Dorimu, đối chiếu + sửa lỗi theo danh mục từ vựng MNN chuẩn
-- Quy tắc: word = kana (+ chú thích sách), reading = CHỈ kana + ～, kanji = kanji (NULL nếu không có)
-- site_id: 1219bda2-aa1e-4288-ab7e-caff011cdf5c

DO $$
DECLARE
  sid uuid := '1219bda2-aa1e-4288-ab7e-caff011cdf5c';
  l7 uuid; l8 uuid; l9 uuid; l10 uuid; l11 uuid; l12 uuid;
BEGIN
SELECT id INTO l7  FROM mnn_lessons WHERE site_id = sid AND lesson_number = 7;
SELECT id INTO l8  FROM mnn_lessons WHERE site_id = sid AND lesson_number = 8;
SELECT id INTO l9  FROM mnn_lessons WHERE site_id = sid AND lesson_number = 9;
SELECT id INTO l10 FROM mnn_lessons WHERE site_id = sid AND lesson_number = 10;
SELECT id INTO l11 FROM mnn_lessons WHERE site_id = sid AND lesson_number = 11;
SELECT id INTO l12 FROM mnn_lessons WHERE site_id = sid AND lesson_number = 12;

IF l7 IS NULL OR l8 IS NULL OR l9 IS NULL OR l10 IS NULL OR l11 IS NULL OR l12 IS NULL THEN
  RAISE EXCEPTION 'mnn_lessons 7-12 chưa tồn tại cho site %', sid;
END IF;

-- ════════════════════════════════════════
-- BÀI 7 — xóa và seed lại (48 từ)
-- ════════════════════════════════════════
DELETE FROM mnn_vocabulary WHERE lesson_id = l7;

-- ════════════════════════════════════════
-- BÀI 8 — xóa và seed lại (55 từ: 52 PDF + tách 暑い/熱い + 2 bổ sung)
-- ════════════════════════════════════════
DELETE FROM mnn_vocabulary WHERE lesson_id = l8;

-- ════════════════════════════════════════
-- BÀI 9 — xóa và seed lại (53 từ: 50 PDF + tách 夫/主人, 妻/家内, 早く/速く)
-- ════════════════════════════════════════
DELETE FROM mnn_vocabulary WHERE lesson_id = l9;

-- ════════════════════════════════════════
-- BÀI 10 — xóa và seed lại (47 từ)
-- ════════════════════════════════════════
DELETE FROM mnn_vocabulary WHERE lesson_id = l10;

-- ════════════════════════════════════════
-- BÀI 11 — xóa và seed lại (57 từ: 56 PDF + tách カレー/カレーライス)
-- ════════════════════════════════════════
DELETE FROM mnn_vocabulary WHERE lesson_id = l11;

-- ════════════════════════════════════════
-- BÀI 12 — xóa và seed lại (49 từ: 47 PDF + tách 速い/早い, 暖かい/温かい)
-- ════════════════════════════════════════
DELETE FROM mnn_vocabulary WHERE lesson_id = l12;

END $$;
